{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Apixaban, a very high-transfer analogue, has an absolute oral bioavailability of 51% in humans after oral dosing, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Vernakalant under fasted conditions, matching the query condition, showed absolute oral bioavailability of 71 ± 21% in healthy volunteers, strongly supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Brepocitinib had an absolute bioavailability of 75% in humans at a 60 mg dose, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Alpelisib showed oral bioavailability around 68.7% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Selpercatinib capsules had a mean absolute bioavailability of 73% in volunteers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Papaverine, with the lowest measured analogue value at 22% absolute bioavailability from a sustained-release product, still meets the F ≥ 20% threshold; other formulations gave 29%, so the evidence remains supportive.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Daridorexant had an absolute bioavailability of 62% in humans, with population PK estimates of 41-53%, all supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability at or above 20%, with most values between 41% and 75%. The fasted-state match and multiple absolute human F measurements support a high prediction, and no affirmative evidence indicates F < 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the exact query molecule.",
    "Some analogue values are near the 20% threshold, but none fall below it.",
    "Query-specific metabolism, transporter effects, and formulation effects are not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

